WITH metrics AS (SELECT *, LAST_VALUE(shipping_fee) IGNORE NULLS OVER (PARTITION BY channel ORDER BY order_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) last_known_shipping_fee, NTILE(5) OVER w_hist amount_bucket FROM orders WHERE shipping_fee < 37 WINDOW w_hist AS (PARTITION BY channel ORDER BY amount, id)) SELECT CASE WHEN amount >= 1690 THEN 'PREMIUM' ELSE 'STANDARD' END AS amount_tier, channel, SUM(CASE WHEN status = 'COMPLETED' THEN amount ELSE 0 END) AS completed_amount, PERCENTILE_APPROX(discount, ARRAY(0.25, 0.5, 0.75)) AS discount_quartiles, MAX(amount_bucket) FILTER (WHERE status = 'SHIPPED') AS shipped_max_amount_bucket, ROUND(AVG(amount), 2) AS avg_amount, ROUND(SUM(discount) / NULLIF(COUNT(CASE WHEN status = 'COMPLETED' THEN 1 END), 0), 2) AS discount_per_completed, GROUPING(CASE WHEN amount >= 1690 THEN 'PREMIUM' ELSE 'STANDARD' END) AS grouping_id FROM metrics GROUP BY GROUPING SETS ((CASE WHEN amount >= 1690 THEN 'PREMIUM' ELSE 'STANDARD' END, channel), (CASE WHEN amount >= 1690 THEN 'PREMIUM' ELSE 'STANDARD' END), ()) HAVING avg_amount > 0 ORDER BY channel DESC;
